program = '' 
manifest = ''
(root / "src/MerzoStream.Setup/Program.cs").write_bytes(unpack(program))
(root / "src/MerzoStream.Setup/app.manifest").write_bytes(unpack(manifest))

csproj = root / "src/MerzoStream.Setup/MerzoStream.Setup.csproj"
text = csproj.read_text(encoding="utf-8-sig")
marker = "    <ApplicationIcon>..\\..\\content\\MerzoStreamSuite.ico</ApplicationIcon>"
if "<ApplicationManifest>app.manifest</ApplicationManifest>" not in text:
    if marker not in text: raise SystemExit("Setup csproj icon marker missing")
    text = text.replace(marker, marker + "\n    <ApplicationManifest>app.manifest</ApplicationManifest>")
