service = root / "src/MerzoStream.Foundation/Services/UpdateService.cs"
s = service.read_text(encoding="utf-8-sig")
old = '    private static void RetargetLaunchPoints(string executable, string runtimeRoot)\n    {\n        try\n        {\n            if (!OperatingSystem.IsWindows()) return;\n            var icon = Path.Combine(runtimeRoot, "content", "MerzoStreamSuite.ico");\n            var shortcuts = new[]\n            {\n                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory), "MerzoStream Suite.lnk"),\n                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu), "Programs", "MerzoStream Suite.lnk")\n            };\n            foreach (var shortcut in shortcuts)\n            {\n                if (File.Exists(shortcut)) CreateOrUpdateShortcut(shortcut, executable, icon);\n            }\n            using var run = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\\Microsoft\\Windows\\CurrentVersion\\Run", writable: true);\n            if (run?.GetValue("MerzoStreamSuite") is not null) run.SetValue("MerzoStreamSuite", $"\\"{executable}\\"");\n        }\n        catch { }\n    }\n'
new = '    private static void RetargetLaunchPoints(string executable, string runtimeRoot)\n    {\n        try\n        {\n            if (!OperatingSystem.IsWindows()) return;\n            var targetExe = executable;\n            var icon = Path.Combine(runtimeRoot, "content", "MerzoStreamSuite.ico");\n\n            // A branded Program Files install keeps one stable launcher (the initially\n            // installed host) and lets that launcher redirect to active-runtime.json.\n            // This prevents OTA updates from turning the visible Windows shortcut back\n            // into a LocalAppData path after every update.\n            var stablePath = Path.Combine(AppPaths.DataDirectory(), "stable-launcher.json");\n            try\n            {\n                if (File.Exists(stablePath))\n                {\n                    using var doc = JsonDocument.Parse(File.ReadAllText(stablePath));\n                    var row = doc.RootElement;\n                    var stableExe = row.TryGetProperty("executable", out var se) ? se.GetString() ?? "" : "";\n                    var stableIcon = row.TryGetProperty("icon", out var si) ? si.GetString() ?? "" : "";\n                    if (!string.IsNullOrWhiteSpace(stableExe) && File.Exists(stableExe))\n                    {\n                        targetExe = stableExe;\n                        if (!string.IsNullOrWhiteSpace(stableIcon) && File.Exists(stableIcon)) icon = stableIcon;\n                    }\n                }\n            }\n            catch { }\n\n            var shortcuts = new[]\n            {\n                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory), "MerzoStream Suite.lnk"),\n                Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu), "Programs", "MerzoStream Suite.lnk")\n            };\n            foreach (var shortcut in shortcuts)\n            {\n                if (File.Exists(shortcut)) CreateOrUpdateShortcut(shortcut, targetExe, icon);\n            }\n            using var run = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\\Microsoft\\Windows\\CurrentVersion\\Run", writable: true);\n            if (run?.GetValue("MerzoStreamSuite") is not null) run.SetValue("MerzoStreamSuite", $"\\"{targetExe}\\"");\n        }\n        catch { }\n    }\n'
if old not in s: raise SystemExit("UpdateService stable-launcher marker missing")
service.write_text(s.replace(old,new), encoding="utf-8", newline="\r\n")

# Generate the approved dark neon M brand asset without external dependencies.
def inside_poly(x,y,pts):
    c=False; j=len(pts)-1
    for i in range(len(pts)):
        xi,yi=pts[i]; xj,yj=pts[j]
        if ((yi>y)!=(yj>y)) and (x < (xj-xi)*(y-yi)/(yj-yi+1e-9)+xi): c=not c
        j=i
    return c

def png_bytes(w=256,h=256):
    pts=[(49,56),(86,56),(128,123),(170,56),(207,56),(207,200),(169,200),(169,125),(128,190),(87,125),(87,200),(49,200)]
    rows=[]; cx=cy=127.5
    for y in range(h):
        row=bytearray([0])
        for x in range(w):
            d=math.hypot(x-cx,y-cy); glow=max(0.0,1-d/170)
            r=int(3+2*glow); g=int(9+8*glow); b=int(18+18*glow)
            m=min(x,y,w-1-x,h-1-y)
            if 7<=m<=10:
                t=x/(w-1); r=int(20*(1-t)+125*t); g=int(220*(1-t)+70*t); b=int(230*(1-t)+255*t)
            if inside_poly(x,y,pts):
                t=(x-49)/(207-49)
                if t<0.65: u=t/0.65; c1=(22,213,241); c2=(49,139,255)
                else: u=(t-0.65)/0.35; c1=(49,139,255); c2=(221,54,238)
                r=int(c1[0]*(1-u)+c2[0]*u); g=int(c1[1]*(1-u)+c2[1]*u); b=int(c1[2]*(1-u)+c2[2]*u)
                if y<72: r=min(255,r+45); g=min(255,g+45); b=min(255,b+45)
            row += bytes((r,g,b,255))
        rows.append(bytes(row))
    raw=b''.join(rows)
    def chunk(t,d): return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(raw,9))+chunk(b'IEND',b'')

png=png_bytes()
ico=struct.pack('<HHH',0,1,1)+struct.pack('<BBBBHHII',0,0,0,0,1,32,len(png),22)+png
(root / "content/MerzoStreamSuite.png").write_bytes(png)
(root / "ui/web/MerzoStreamSuite.png").write_bytes(png)
(root / "content/MerzoStreamSuite.ico").write_bytes(ico)

